-- Trang "Chép câu": thêm thư mục "12 hướng phát triển ý · pattern mục 2" gồm 100 câu luyện dịch Việt → Anh.
-- Nội dung lấy từ 12 hướng phát triển ý (mục 3), mỗi câu dùng 1 pattern khác nhau ở mục 2.1–2.12
-- của DATA/huong-dan-song-ngu.html. Chủ đề của câu = tên hướng, để lọc theo hướng trong thư mục.
-- Chạy trong Supabase → SQL Editor. An toàn khi chạy lại: đã có thư mục cùng tên thì bỏ qua.

do $$
declare
  -- Email đăng nhập app. Để trống = tự lấy tài khoản có thư mục "01. ..." (bộ 01–15 hiện có).
  v_email  text := '';
  v_name   text := '12 hướng phát triển ý · pattern mục 2';
  v_user   uuid;
  v_count  int;
  v_folder uuid;
  v_now    timestamptz := now();
begin
  if v_email <> '' then
    select id into v_user from auth.users where lower(email) = lower(v_email);
    if v_user is null then
      raise exception 'Không có tài khoản nào với email %', v_email;
    end if;
  else
    select count(distinct user_id), min(user_id::text)::uuid into v_count, v_user
    from public.sentence_folders
    where name like '01.%' and deleted_at is null;
    if v_count <> 1 then
      raise exception 'Tìm thấy % tài khoản có thư mục "01. ...". Hãy điền v_email ở đầu script.', v_count;
    end if;
  end if;

  if exists (
    select 1 from public.sentence_folders
    where user_id = v_user and name = v_name and deleted_at is null
  ) then
    raise notice 'Thư mục "%" đã có, bỏ qua.', v_name;
    return;
  end if;

  insert into public.sentence_folders (user_id, name)
  values (v_user, v_name)
  returning id into v_folder;

  -- App xếp câu theo created_at: cách nhau 1 ms để giữ đúng thứ tự 1 → 100
  insert into public.sentences
    (user_id, folder_id, vi, en, alt_answers, hints, level, topic, created_at, updated_at)
  select v_user, v_folder, s.vi, s.en, s.alt, s.hints, s.level, s.topic,
         v_now + s.n * interval '1 millisecond', v_now + s.n * interval '1 millisecond'
  from (values
    (1, 'Trợ cấp của chính phủ có thể khuyến khích các hộ gia đình lắp tấm pin mặt trời.', 'Government subsidies can encourage households to install solar panels.', '["Government subsidies could encourage households to install solar panels.","State subsidies can encourage households to install solar panels.","Government subsidies can encourage families to install solar panels."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","subsidies = trợ cấp; install solar panels = lắp tấm pin mặt trời"]'::jsonb, 'B1', '1. Chính phủ'),
    (2, 'Phí đỗ xe cao ở trung tâm thành phố khiến người lái xe ngại dùng ô tô riêng.', 'High parking fees in city centres discourage drivers from using private cars.', '["High parking fees in city centers discourage drivers from using private cars.","High parking charges in city centres discourage drivers from using private cars.","High parking fees in city centres discourage drivers from using their own cars."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","parking fees = phí đỗ xe"]'::jsonb, 'B2', '1. Chính phủ'),
    (3, 'Luật nên yêu cầu các nhà máy công khai lượng khí thải của họ.', 'The law should require factories to publish their emission levels.', '["The law should require factories to disclose their emission levels.","The law should require factories to make their emission levels public.","Laws should require factories to publish their emission levels."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","publish / disclose = công khai; emission levels = lượng khí thải"]'::jsonb, 'B2', '1. Chính phủ'),
    (4, 'Chính phủ có thể đánh thuế đồ uống có đường, điều này đến lượt nó sẽ làm giảm tỷ lệ béo phì.', 'The government could tax sugary drinks, which would in turn reduce obesity rates.', '["The government could impose a tax on sugary drinks, which would in turn reduce obesity rates.","The government could tax sugary drinks, which would in turn lower obesity rates.","The government can tax sugary drinks, which will in turn reduce obesity rates."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","obesity rates = tỷ lệ béo phì"]'::jsonb, 'C1', '1. Chính phủ'),
    (5, 'Tôi cho rằng chính phủ là bên có vị thế tốt nhất để giải quyết vấn đề này.', 'I would argue that the government is in the best position to tackle this problem.', '["I would argue that the government is in the best position to solve this problem.","I would argue that governments are in the best position to tackle this problem.","I would argue that the government is best placed to tackle this problem."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","be in the best position to V = có vị thế tốt nhất để"]'::jsonb, 'C1', '1. Chính phủ'),
    (6, 'Phải thừa nhận là luật mới thường không được ưa chuộng lúc đầu; dù vậy, chúng mang lại thay đổi lâu dài.', 'Admittedly, new laws are often unpopular at first; nevertheless, they bring about lasting change.', '["Admittedly, new laws are often unpopular at first; nevertheless, they bring lasting change.","Admittedly, new laws are often unpopular at the beginning; nevertheless, they bring about lasting change.","Admittedly, new laws are usually unpopular at first; nevertheless, they bring about lasting change."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","bring about lasting change = mang lại thay đổi lâu dài"]'::jsonb, 'C1', '1. Chính phủ'),
    (7, 'Chính quyền phải áp dụng các biện pháp để cải thiện chất lượng không khí ở các thành phố lớn.', 'The authorities must take measures to improve air quality in big cities.', '["The authorities must take steps to improve air quality in big cities.","The authorities must take measures to improve the air quality in big cities.","The authorities must take measures to improve air quality in large cities.","The authorities have to take measures to improve air quality in big cities."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.8)","the authorities = chính quyền; air quality = chất lượng không khí"]'::jsonb, 'B2', '1. Chính phủ'),
    (8, 'Nếu chính phủ đầu tư nhiều hơn vào giao thông công cộng, tình trạng kẹt xe sẽ giảm bớt.', 'Were the government to invest more in public transport, traffic congestion would ease.', '["Were the government to invest more in public transport, traffic congestion would decrease.","Were the government to invest more in public transport, traffic jams would ease.","Were the government to invest more in public transportation, traffic congestion would ease."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.9)","đảo ngữ, không dùng If; traffic congestion = kẹt xe"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 'Các chiến dịch công cộng có thể nâng cao nhận thức về tác hại của việc lái xe khi say rượu.', 'Public campaigns can raise awareness of the dangers of drink-driving.', '["Public campaigns can raise awareness of the dangers of drunk driving.","Public campaigns can raise awareness of the harmful effects of drink-driving.","Public campaigns can raise awareness about the dangers of drink-driving."]'::jsonb, '["raise awareness of sth = nâng cao nhận thức về (mục 2.12)","drink-driving = lái xe khi say rượu"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 'Tấm gương của một người có thể thuyết phục bạn bè thay đổi thói quen mua sắm.', 'One person''s example can persuade their friends to change their shopping habits.', '["One person''s example can persuade friends to change their shopping habits.","A single person''s example can persuade their friends to change their shopping habits.","One person''s example can persuade their friends to change the way they shop."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","shopping habits = thói quen mua sắm"]'::jsonb, 'B2', '2. Cá nhân'),
    (11, 'Nhiều người không tiết kiệm được tiền vì họ mua sắm theo cảm hứng.', 'Many people fail to save money because they shop on impulse.', '["Many people cannot save money because they shop on impulse.","Many people fail to save money because they buy things on impulse.","Many people are unable to save money because they shop on impulse.","Many people fail to save money because of impulse shopping."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","on impulse = theo cảm hứng, bốc đồng"]'::jsonb, 'B1', '2. Cá nhân'),
    (12, 'Tôi tin rằng mỗi người nên chịu trách nhiệm về lượng rác mình thải ra.', 'I believe that every individual should be responsible for the waste they produce.', '["I think that every individual should be responsible for the waste they produce.","I believe that everyone should be responsible for the waste they produce.","I believe every individual should be responsible for the waste they produce.","I believe that each person should be responsible for the waste they produce."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","be responsible for sth = chịu trách nhiệm về"]'::jsonb, 'B1', '2. Cá nhân'),
    (13, 'Khi hàng triệu người cùng tham gia, những hành động nhỏ hằng ngày có thể hiệu quả ngang các dự án lớn của chính phủ.', 'When millions of people take part, small daily actions can be as effective as large government projects.', '["When millions of people take part, small everyday actions can be as effective as large government projects.","When millions of people participate, small daily actions can be as effective as large government projects.","Small daily actions can be as effective as large government projects when millions of people take part."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","take part = tham gia"]'::jsonb, 'B1', '2. Cá nhân'),
    (14, 'Một cách để giảm rác thải sinh hoạt là mua ít sản phẩm đóng gói sẵn hơn.', 'One way to reduce household waste is to buy fewer packaged products.', '["One way to cut household waste is to buy fewer packaged products.","One way to reduce household rubbish is to buy fewer packaged products.","One way to reduce household waste is to buy less packaged food."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.8)","household waste = rác thải sinh hoạt; fewer + danh từ số nhiều"]'::jsonb, 'B1', '2. Cá nhân'),
    (15, 'Nếu mọi người tắt những bóng đèn không cần thiết, lượng điện tiêu thụ sẽ giảm.', 'If everyone turns off unnecessary lights, electricity consumption will fall.', '["If everyone switches off unnecessary lights, electricity consumption will fall.","If everyone turns off unnecessary lights, electricity consumption will decrease.","If people turn off unnecessary lights, electricity consumption will fall.","If everyone turns off unnecessary lights, power consumption will fall."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.9)","everyone + động từ số ít (turns); electricity consumption = lượng điện tiêu thụ"]'::jsonb, 'B1', '2. Cá nhân'),
    (16, 'Nếu mỗi cá nhân phớt lờ vấn đề này, nó sẽ chỉ ngày càng tệ hơn.', 'Should individuals ignore this problem, it will only get worse.', '["Should individuals ignore this problem, it will only become worse.","Should individuals ignore the problem, it will only get worse.","Should people ignore this problem, it will only get worse."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.9)","đảo ngữ, không dùng If; ignore = phớt lờ"]'::jsonb, 'C1', '2. Cá nhân'),
    (17, 'Mọi người hiếm khi nghĩ xem rác của mình cuối cùng sẽ đi về đâu.', 'Rarely do people think about where their rubbish ends up.', '["Rarely do people think about where their waste ends up.","Rarely do people think about where their garbage ends up.","Rarely do people think about where their trash ends up.","Rarely do people consider where their rubbish ends up."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.10)","end up = cuối cùng đi đến đâu"]'::jsonb, 'C1', '2. Cá nhân'),
    (18, 'Những người tình nguyện đóng góp đáng kể cho cộng đồng địa phương.', 'Volunteers make a significant contribution to their local communities.', '["Volunteers make a significant contribution to the local community.","Volunteers make a significant contribution to local communities.","Volunteers make a considerable contribution to their local communities.","Volunteers make a great contribution to their local communities."]'::jsonb, '["make a contribution to sth = đóng góp cho (mục 2.12)","significant = đáng kể"]'::jsonb, 'B2', '2. Cá nhân'),
    (19, 'Trường học nên trang bị cho học sinh kỹ năng tư duy phản biện.', 'Schools should equip students with critical thinking skills.', '["Schools should equip pupils with critical thinking skills.","Schools ought to equip students with critical thinking skills.","Schools should equip students with the ability to think critically."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","critical thinking = tư duy phản biện"]'::jsonb, 'B2', '3. Trường học'),
    (20, 'Nhiều trường cấm học sinh dùng điện thoại trong giờ học.', 'Many schools prohibit students from using mobile phones during lessons.', '["Many schools ban students from using mobile phones during lessons.","Many schools prohibit students from using their phones during lessons.","Many schools prohibit students from using phones during lessons.","Many schools prohibit students from using mobile phones in class."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","during lessons = trong giờ học"]'::jsonb, 'C1', '3. Trường học'),
    (21, 'Theo tôi, nhà trường nên dạy kỹ năng tài chính như một môn bắt buộc.', 'In my opinion, schools should teach financial skills as a compulsory subject.', '["In my opinion, schools should teach financial skills as a required subject.","In my opinion, schools should teach money skills as a compulsory subject.","In my opinion, schools should make financial skills a compulsory subject."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","compulsory subject = môn bắt buộc"]'::jsonb, 'B1', '3. Trường học'),
    (22, 'Những bài học thực hành thường hữu ích hơn việc học thuộc lòng kiến thức.', 'Practical lessons are often more useful than memorising facts.', '["Practical lessons are often more useful than memorizing facts.","Practical lessons are usually more useful than memorising facts.","Practical lessons are often more useful than learning facts by heart.","Hands-on lessons are often more useful than memorising facts."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","memorise facts = học thuộc kiến thức"]'::jsonb, 'B1', '3. Trường học'),
    (23, 'Các lớp học nhỏ vượt trội hơn các lớp đông về mức độ quan tâm mà mỗi học sinh nhận được.', 'Small classes are superior to large ones in terms of the attention each student receives.', '["Small classes are superior to large classes in terms of the attention each student receives.","Small classes are superior to big ones in terms of the attention each student receives.","Small classes are superior to large ones in terms of the attention every student receives.","Small classes are superior to large ones in terms of the attention each student gets."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","in terms of = về mặt"]'::jsonb, 'C1', '3. Trường học'),
    (24, 'Một giáo viên giỏi là yếu tố quan trọng nhất, bỏ xa các yếu tố khác, đối với kết quả học tập của học sinh.', 'A good teacher is by far the most important factor in students'' academic performance.', '["A good teacher is by far the most important factor in students'' academic results.","A good teacher is by far the most important factor in students'' academic success.","Good teachers are by far the most important factor in students'' academic performance."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","academic performance = kết quả học tập"]'::jsonb, 'C1', '3. Trường học'),
    (25, 'Các trường nên hướng nghiệp nhiều hơn cho học sinh năm cuối.', 'Schools should offer more career guidance to final-year students.', '["Schools should provide more career guidance to final-year students.","Schools should give more career guidance to final-year students.","Schools should offer final-year students more career guidance.","Schools ought to offer more career guidance to final-year students."]'::jsonb, '["should / ought to + V = nên (mục 2.8)","career guidance = hướng nghiệp; final-year students = học sinh năm cuối"]'::jsonb, 'B1', '3. Trường học'),
    (26, 'Lý do nhiều học sinh mất hứng thú với môn khoa học là vì các bài học quá nặng lý thuyết.', 'The reason why many students lose interest in science is that the lessons are too theoretical.', '["The reason why many students lose interest in science is that lessons are too theoretical.","The reason why many pupils lose interest in science is that the lessons are too theoretical.","The reason why many students lose interest in science subjects is that the lessons are too theoretical."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.10)","lose interest in sth = mất hứng thú với; theoretical = nặng lý thuyết"]'::jsonb, 'C1', '3. Trường học'),
    (27, 'Giáo viên đóng vai trò quan trọng trong việc hình thành thái độ của học sinh đối với môi trường.', 'Teachers play an important role in shaping students'' attitudes towards the environment.', '["Teachers play an important role in shaping students'' attitudes toward the environment.","Teachers play an important role in forming students'' attitudes towards the environment.","Teachers play an important role in shaping the attitudes of students towards the environment."]'::jsonb, '["play an important role in sth = đóng vai trò quan trọng trong (mục 2.12)","shape attitudes = hình thành thái độ"]'::jsonb, 'B1', '3. Trường học'),
    (28, 'Cha mẹ có thể ngăn con dành hàng giờ trên điện thoại bằng cách đặt ra quy tắc rõ ràng.', 'Parents can stop their children from spending hours on their phones by setting clear rules.', '["Parents can stop their children spending hours on their phones by setting clear rules.","Parents can stop children from spending hours on their phones by setting clear rules.","Parents can stop their kids from spending hours on their phones by setting clear rules.","Parents can stop their children from spending hours on their phones by making clear rules."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","by + V-ing = bằng cách; set rules = đặt ra quy tắc"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (29, 'Tôi tin chắc rằng cha mẹ là những người thầy đầu tiên và quan trọng nhất của con.', 'I am convinced that parents are their children''s first and most important teachers.', '["I''m convinced that parents are their children''s first and most important teachers.","I am convinced that parents are the first and most important teachers of their children.","I am convinced that parents are children''s first and most important teachers."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","first and most important = đầu tiên và quan trọng nhất"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (30, 'Nhà trường dạy kiến thức, trong khi cha mẹ hình thành giá trị sống cho con.', 'Schools teach knowledge, whereas parents shape their children''s values.', '["Schools teach knowledge, while parents shape their children''s values.","Schools provide knowledge, whereas parents shape their children''s values.","Schools teach knowledge, whereas parents shape children''s values.","Schools teach knowledge, whereas parents shape their children''s values in life."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","shape values = hình thành giá trị"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (31, 'So với nhà trường, cha mẹ ảnh hưởng đến tính cách của trẻ sớm hơn.', 'Compared with schools, parents influence children''s character earlier.', '["Compared with schools, parents have an earlier influence on children''s character.","In comparison with schools, parents influence children''s character earlier.","Compared to schools, parents influence children''s character earlier.","Compared with schools, parents influence their children''s character earlier."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","influence (v) = ảnh hưởng đến; character = tính cách"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (32, 'Điều thiết yếu là cha mẹ phải dành thời gian chất lượng cho con mỗi ngày.', 'It is essential that parents spend quality time with their children every day.', '["It is essential that parents should spend quality time with their children every day.","It is vital that parents spend quality time with their children every day.","It''s essential that parents spend quality time with their children every day.","It is essential that parents spend quality time with their kids every day."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.8)","sau that: S + (should) + V nguyên mẫu; quality time = thời gian chất lượng"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (33, 'Chính ở nhà, trẻ em học những bài học đầu tiên về sự tôn trọng.', 'It is at home that children learn their first lessons about respect.', '["It''s at home that children learn their first lessons about respect.","It is at home that children learn their first lessons in respect.","It is at home that children learn their first lessons of respect."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.10)","It is + [phần nhấn mạnh] + that + S + V"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (34, 'Ngày càng có xu hướng cha mẹ dùng máy tính bảng để giữ trẻ nhỏ ngồi yên.', 'There is a growing tendency for parents to use tablets to keep young children quiet.', '["There is a growing tendency for parents to use tablets to keep young children still.","There is a growing tendency for parents to use tablets to keep small children quiet.","There is a growing tendency for parents to use tablets to keep their young children quiet.","There is a growing tendency for parents to use tablets to keep young children calm."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.11)","keep sb quiet = giữ ai ngồi yên"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (35, 'Việc dùng Internet không có người giám sát có thể đe dọa nghiêm trọng đến sự an toàn của trẻ.', 'Unsupervised Internet use can pose a serious threat to children''s safety.', '["Unsupervised use of the Internet can pose a serious threat to children''s safety.","Unsupervised Internet use could pose a serious threat to children''s safety.","Unsupervised Internet use can pose a serious threat to the safety of children."]'::jsonb, '["pose a (serious) threat to sth = đe dọa (nghiêm trọng) đến (mục 2.12)","unsupervised = không có người giám sát"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (36, 'Với cha mẹ, điện thoại thông minh là con dao hai lưỡi, vì nó giúp con giữ liên lạc nhưng cũng khiến con xao nhãng việc học.', 'For parents, smartphones are a double-edged sword, as they keep children connected but also distract them from studying.', '["For parents, smartphones are a double-edged sword because they keep children connected but also distract them from studying.","For parents, smartphones are a double-edged sword, as they keep children connected but also distract them from their studies.","For parents, the smartphone is a double-edged sword, as it keeps children connected but also distracts them from studying."]'::jsonb, '["a double-edged sword = con dao hai lưỡi (mục 2.12)","distract sb from sth = khiến ai xao nhãng"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (37, 'Nhà tuyển dụng nên cung cấp cho nhân viên các khóa đào tạo thường xuyên.', 'Employers should provide their staff with regular training courses.', '["Employers should provide staff with regular training courses.","Employers should provide their employees with regular training courses.","Employers should provide their staff with regular training.","Employers ought to provide their staff with regular training courses."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","staff = nhân viên; training courses = khóa đào tạo"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (38, 'Giờ làm việc kéo dài khiến nhân viên cảm thấy kiệt sức và làm việc kém hiệu quả hơn.', 'Long working hours make employees feel exhausted and less productive.', '["Long working hours make staff feel exhausted and less productive.","Long working hours make workers feel exhausted and less productive.","Long working hours make employees feel exhausted and become less productive."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","make sb + V nguyên mẫu (không có to); productive = làm việc hiệu quả"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (39, 'Cạnh tranh gay gắt buộc các công ty nhỏ phải cắt giảm chi phí.', 'Fierce competition forces small companies to cut costs.', '["Fierce competition compels small companies to cut costs.","Fierce competition forces small businesses to cut costs.","Fierce competition forces small companies to reduce costs.","Intense competition forces small companies to cut costs."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","fierce competition = cạnh tranh gay gắt"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (40, 'Công nghệ xanh tốn kém khi lắp đặt; tuy nhiên, nó giúp doanh nghiệp tiết kiệm tiền về lâu dài.', 'Green technology is expensive to install; however, it saves businesses money in the long run.', '["Green technology is costly to install; however, it saves businesses money in the long run.","Green technology is expensive to install; however, it helps businesses save money in the long run.","Green technology is expensive to install, but it saves businesses money in the long run."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","save sb money = giúp ai tiết kiệm tiền; in the long run = về lâu dài"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (41, 'Ví dụ, nhiều công ty hiện nay cho nhân viên khám sức khỏe miễn phí.', 'For example, many companies now offer their employees free health checks.', '["For instance, many companies now offer their employees free health checks.","For example, many companies now offer free health checks to their employees.","For example, many companies now offer their staff free health checks.","For example, many companies now provide their employees with free health checks."]'::jsonb, '["for example / for instance = ví dụ (mục 2.7)","health checks = khám sức khỏe"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (42, 'Nhà tuyển dụng cần giải quyết vấn đề căng thẳng nơi làm việc.', 'Employers need to tackle the problem of workplace stress.', '["Employers need to address the problem of workplace stress.","Employers need to combat the problem of workplace stress.","Employers need to tackle the problem of stress at work.","Employers need to tackle the issue of workplace stress."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.8)","workplace stress = căng thẳng nơi làm việc"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (43, 'Ngày càng có nhiều công ty chuyển sang dùng bao bì có thể tái chế.', 'An increasing number of companies are switching to recyclable packaging.', '["A growing number of companies are switching to recyclable packaging.","An increasing number of businesses are switching to recyclable packaging.","An increasing number of companies are turning to recyclable packaging.","An increasing number of companies are moving to recyclable packaging."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.11)","N số nhiều + động từ số nhiều; recyclable packaging = bao bì tái chế được"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (44, 'Các doanh nghiệp phải chịu trách nhiệm về ô nhiễm mà họ gây ra.', 'Businesses must take responsibility for the pollution they cause.', '["Businesses must take responsibility for the pollution that they cause.","Companies must take responsibility for the pollution they cause.","Businesses have to take responsibility for the pollution they cause.","Businesses must take responsibility for the pollution they create."]'::jsonb, '["take responsibility for sth = chịu trách nhiệm về (mục 2.12)","the pollution (that) they cause = ô nhiễm mà họ gây ra"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (45, 'Tập thể dục đều đặn giúp người trung niên giảm nguy cơ mắc bệnh tim.', 'Regular exercise helps middle-aged people reduce the risk of heart disease.', '["Regular exercise helps middle-aged people to reduce the risk of heart disease.","Regular exercise helps middle-aged people lower the risk of heart disease.","Regular exercise helps middle-aged people reduce their risk of heart disease."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","reduce the risk of = giảm nguy cơ; middle-aged = trung niên"]'::jsonb, 'B1', '6. Sức khỏe'),
    (46, 'Nhiều nhân viên văn phòng ngồi cả ngày, vì vậy họ dễ bị đau lưng.', 'Many office workers sit all day, so they are prone to back pain.', '["Many office workers sit all day. As a result, they are prone to back pain.","Many office workers sit all day, so they often suffer from back pain.","Many office workers sit all day, so they easily get back pain.","Many office workers sit all day, so they are likely to get back pain."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","be prone to sth = dễ bị"]'::jsonb, 'B1', '6. Sức khỏe'),
    (47, 'Sự gia tăng bệnh tiểu đường phần lớn là do chế độ ăn nhiều đường.', 'The rise in diabetes is largely attributable to diets high in sugar.', '["The rise in diabetes is largely attributable to high-sugar diets.","The increase in diabetes is largely attributable to diets high in sugar.","The rise in diabetes is largely attributable to a diet high in sugar.","The rise in diabetes is largely attributable to sugary diets."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","the rise in sth = sự gia tăng; diets high in sugar = chế độ ăn nhiều đường"]'::jsonb, 'C1', '6. Sức khỏe'),
    (48, 'Nhiều người tin rằng khám sức khỏe định kỳ có thể cứu sống nhiều người.', 'It is widely believed that regular check-ups can save many lives.', '["It is widely believed that regular health check-ups can save many lives.","It is widely believed that regular medical check-ups can save many lives.","It is widely believed that regular checkups can save many lives.","Regular check-ups are widely believed to save many lives."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","regular check-ups = khám định kỳ"]'::jsonb, 'C1', '6. Sức khỏe'),
    (49, 'Đi bộ hoặc đạp xe đi làm tốt cho sức khỏe hơn nhiều so với lái xe.', 'Walking or cycling to work is far healthier than driving.', '["Walking or cycling to work is much healthier than driving.","Walking or cycling to work is considerably healthier than driving.","Walking or cycling to work is far better for your health than driving."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","healthy → healthier"]'::jsonb, 'B2', '6. Sức khỏe'),
    (50, 'Một chế độ ăn cân bằng không những giúp kiểm soát cân nặng mà còn tăng cường hệ miễn dịch.', 'A balanced diet not only helps people control their weight but also strengthens their immune system.', '["A balanced diet not only helps people to control their weight but also strengthens their immune system.","A balanced diet not only helps control weight but also strengthens the immune system.","A balanced diet not only helps people control their weight but also boosts their immune system.","A balanced diet not only helps people manage their weight but also strengthens their immune system."]'::jsonb, '["not only … but (also) … = không những … mà còn … (mục 2.7)","immune system = hệ miễn dịch"]'::jsonb, 'B2', '6. Sức khỏe'),
    (51, 'Mãi đến khi mắc bệnh mãn tính, nhiều người mới bắt đầu tập thể dục đều đặn.', 'Not until they develop a chronic illness do many people start to exercise regularly.', '["Not until they develop a chronic illness do many people start exercising regularly.","Not until they develop a chronic disease do many people start to exercise regularly.","Not until they suffer from a chronic illness do many people start to exercise regularly."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.10)","chronic illness = bệnh mãn tính"]'::jsonb, 'C1', '6. Sức khỏe'),
    (52, 'Mọi người nên chú ý nhiều hơn đến sức khỏe tinh thần của mình.', 'People should pay more attention to their mental health.', '["People should pay more attention to their own mental health.","Everyone should pay more attention to their mental health.","People ought to pay more attention to their mental health."]'::jsonb, '["pay attention to sth = chú ý đến (mục 2.12)","mental health = sức khỏe tinh thần"]'::jsonb, 'B1', '6. Sức khỏe'),
    (53, 'Đào tạo nghề tiếp sức cho người thất nghiệp tìm được việc làm lương cao hơn.', 'Vocational training empowers unemployed people to find better-paid jobs.', '["Vocational training empowers unemployed workers to find better-paid jobs.","Vocational training empowers the unemployed to find better-paid jobs.","Vocational training empowers unemployed people to find higher-paid jobs.","Vocational training empowers unemployed people to get better-paid jobs."]'::jsonb, '["empower sb to do sth = trao quyền, tiếp sức cho ai làm gì (mục 2.1)","vocational training = đào tạo nghề; better-paid jobs = việc làm lương cao hơn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (54, 'Tình trạng thiếu lao động có tay nghề cản trở tăng trưởng kinh tế.', 'A shortage of skilled workers hinders economic growth.', '["A shortage of skilled workers impedes economic growth.","A lack of skilled workers hinders economic growth.","The shortage of skilled workers hinders economic growth.","A shortage of skilled labour hinders economic growth."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","a shortage of = tình trạng thiếu; skilled workers = lao động có tay nghề"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (55, 'Nhiều gia đình đang gặp khó khăn do chi phí sinh hoạt tăng cao.', 'Many families are struggling due to the rising cost of living.', '["Many families are struggling owing to the rising cost of living.","Many families are having difficulties due to the rising cost of living.","Many families are struggling due to the high cost of living.","Many families are struggling due to rising living costs."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","the cost of living = chi phí sinh hoạt"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (56, 'Lạm phát cao cộng với lãi suất tăng khiến nhiều doanh nghiệp nhỏ phải hoãn kế hoạch mở rộng.', 'High inflation, coupled with rising interest rates, means that many small businesses have to delay their expansion plans.', '["High inflation, coupled with rising interest rates, means that many small businesses must delay their expansion plans.","High inflation, coupled with rising interest rates, means that many small businesses have to postpone their expansion plans.","High inflation, coupled with rising interest rates, means many small businesses have to delay their expansion plans.","High inflation, coupled with higher interest rates, means that many small businesses have to delay their expansion plans."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","inflation = lạm phát; interest rates = lãi suất"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (57, 'Một ví dụ tiêu biểu là Hàn Quốc, nước đã phát triển nhanh nhờ đầu tư vào giáo dục và công nghệ.', 'A case in point is South Korea, which developed rapidly by investing in education and technology.', '["A case in point is South Korea, which grew rapidly by investing in education and technology.","A case in point is South Korea, which developed quickly by investing in education and technology.","A case in point is South Korea, which developed rapidly thanks to investment in education and technology."]'::jsonb, '["A case in point is … = một ví dụ tiêu biểu là (mục 2.7)","by + V-ing = nhờ, bằng cách"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (58, 'Nếu chính phủ đưa ra ưu đãi thuế, sẽ có nhiều công ty nước ngoài đầu tư vào đất nước hơn.', 'If the government offered tax incentives, more foreign companies would invest in the country.', '["If the government offered tax breaks, more foreign companies would invest in the country.","If the government provided tax incentives, more foreign companies would invest in the country.","If the government introduced tax incentives, more foreign companies would invest in the country.","If the government offered tax incentives, more foreign firms would invest in the country."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.9)","tax incentives = ưu đãi thuế"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (59, 'Nhà máy mới được dự đoán sẽ tạo ra hàng nghìn việc làm cho người dân địa phương.', 'The new factory is expected to create thousands of jobs for local people.', '["The new factory is expected to create thousands of jobs for local residents.","The new factory is expected to create thousands of jobs for locals.","The new plant is expected to create thousands of jobs for local people.","The new factory is expected to provide thousands of jobs for local people."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.11)","create jobs = tạo việc làm"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (60, 'Nhiều nước đang đào tạo thêm kỹ sư phần mềm để đáp ứng nhu cầu về kỹ năng số.', 'Many countries are training more software engineers to meet the demand for digital skills.', '["Many nations are training more software engineers to meet the demand for digital skills.","Many countries are training more software developers to meet the demand for digital skills.","Many countries are training more software engineers in order to meet the demand for digital skills."]'::jsonb, '["meet the demand for sth = đáp ứng nhu cầu về (mục 2.12)","digital skills = kỹ năng số"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (61, 'Các trung tâm cộng đồng giúp người cao tuổi có thể gặp gỡ bạn mới.', 'Community centres make it possible for elderly people to meet new friends.', '["Community centers make it possible for elderly people to meet new friends.","Community centres make it possible for elderly people to make new friends.","Community centres make it possible for older people to meet new friends.","Community centres make it possible for the elderly to meet new friends."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","community centres = trung tâm cộng đồng"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (62, 'Đèn đường sáng hơn có thể răn đe tội phạm không nhắm vào các khu dân cư.', 'Better street lighting can deter criminals from targeting residential areas.', '["Brighter street lighting can deter criminals from targeting residential areas.","Better street lighting could deter criminals from targeting residential areas.","Better street lights can deter criminals from targeting residential areas.","Better street lighting can deter criminals from targeting residential neighbourhoods."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","residential areas = khu dân cư"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (63, 'Sự cô đơn ở người già thường bắt nguồn từ việc sống xa gia đình.', 'Loneliness among the elderly often stems from living far away from their families.', '["Loneliness among the elderly often stems from living far from their families.","Loneliness among elderly people often stems from living far away from their families.","Loneliness among old people often stems from living far away from their families.","Loneliness among the elderly is often caused by living far away from their families."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","loneliness = sự cô đơn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (64, 'Dù sống ở những thành phố đông đúc, nhiều người vẫn cảm thấy cô đơn.', 'Despite living in crowded cities, many people still feel lonely.', '["In spite of living in crowded cities, many people still feel lonely.","Despite living in crowded cities, many people feel lonely.","Despite living in busy cities, many people still feel lonely.","Despite living in densely populated cities, many people still feel lonely."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing (không dùng despite + mệnh đề)"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (65, 'Một ví dụ điển hình là Nhật Bản, nơi nhiều thị trấn tổ chức bữa ăn chung cho người già sống một mình.', 'A good example of this is Japan, where many towns organise shared meals for elderly people who live alone.', '["A good example of this is Japan, where many towns organize shared meals for elderly people who live alone.","A good example of this is Japan, where many towns organise community meals for elderly people who live alone.","A good example of this is Japan, where many towns organise shared meals for old people who live alone.","A good example of this is Japan, where many towns hold shared meals for elderly people living alone."]'::jsonb, '["A good example of this is … = một ví dụ điển hình là (mục 2.7)","live alone = sống một mình"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (66, 'Các hoạt động cộng đồng miễn phí sẽ góp phần lớn vào việc giảm sự cô lập xã hội.', 'Free community activities would go a long way towards reducing social isolation.', '["Free community activities would go a long way toward reducing social isolation.","Free community activities will go a long way towards reducing social isolation.","Free community activities could go a long way towards reducing social isolation.","Free community activities would go a long way towards tackling social isolation."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.8)","social isolation = sự cô lập xã hội"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (67, 'Cộng đồng nên cùng nhau chăm sóc những người khuyết tật trong khu phố.', 'Communities should work together to take care of disabled people in their neighbourhood.', '["Communities should work together to take care of disabled people in their neighborhood.","Communities should work together to take care of people with disabilities in their neighbourhood.","Communities should work together to take care of the disabled in their neighbourhood.","Communities should join together to take care of disabled people in their neighbourhood."]'::jsonb, '["take care of sb / sth = chăm sóc (mục 2.12)","disabled people = người khuyết tật; neighbourhood = khu phố"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (68, 'Dịch vụ công miễn phí có thể giúp thu hẹp khoảng cách giữa người giàu và người nghèo.', 'Free public services can help bridge the gap between the rich and the poor.', '["Free public services can help to bridge the gap between the rich and the poor.","Free public services can bridge the gap between the rich and the poor.","Free public services can help bridge the gap between rich and poor people.","Free public services can help bridge the gap between rich and poor."]'::jsonb, '["bridge the gap between A and B = thu hẹp khoảng cách giữa A và B (mục 2.12)","the rich / the poor = người giàu / người nghèo"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (69, 'Tiêu chuẩn khí thải nghiêm ngặt hơn sẽ ngăn các nhà máy thải khói độc ra không khí.', 'Stricter emission standards would prevent factories from releasing toxic fumes into the air.', '["Stricter emission standards will prevent factories from releasing toxic fumes into the air.","Tougher emission standards would prevent factories from releasing toxic fumes into the air.","Stricter emission standards would prevent factories from releasing toxic smoke into the air.","Stricter emission standards would prevent factories from emitting toxic fumes into the air."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","emission standards = tiêu chuẩn khí thải; toxic fumes = khói độc"]'::jsonb, 'B2', '9. Môi trường'),
    (70, 'Tiêu dùng quá mức dẫn đến lượng rác thải nhựa khổng lồ.', 'Overconsumption results in huge amounts of plastic waste.', '["Overconsumption results in enormous amounts of plastic waste.","Overconsumption results in a huge amount of plastic waste.","Excessive consumption results in huge amounts of plastic waste.","Over-consumption results in huge amounts of plastic waste."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","overconsumption = tiêu dùng quá mức"]'::jsonb, 'B2', '9. Môi trường'),
    (71, 'Tôi kiên quyết cho rằng năng lượng sạch là lựa chọn bền vững duy nhất cho tương lai.', 'I am firmly of the view that clean energy is the only sustainable option for the future.', '["I am firmly of the view that clean energy is the only sustainable choice for the future.","I am firmly of the view that renewable energy is the only sustainable option for the future.","I''m firmly of the view that clean energy is the only sustainable option for the future."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","sustainable = bền vững"]'::jsonb, 'C1', '9. Môi trường'),
    (72, 'Càng nhiều người dùng phương tiện công cộng, không khí ở thành phố càng sạch.', 'The more people use public transport, the cleaner the air in cities becomes.', '["The more people use public transport, the cleaner the city air becomes.","The more people use public transport, the cleaner the air in the city becomes.","The more people use public transport, the cleaner the air in cities will be.","The more people use public transportation, the cleaner the air in cities becomes."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","clean → the cleaner"]'::jsonb, 'C1', '9. Môi trường'),
    (73, 'Những việc đơn giản như tái chế và mang túi vải khi đi chợ có thể giảm đáng kể rác thải.', 'Simple actions such as recycling and taking cloth bags to the market can significantly reduce waste.', '["Simple actions such as recycling and bringing cloth bags to the market can significantly reduce waste.","Simple actions such as recycling and taking cloth bags to the market can reduce waste significantly.","Simple things such as recycling and taking cloth bags to the market can significantly reduce waste.","Simple actions such as recycling and taking reusable bags to the market can significantly reduce waste."]'::jsonb, '["such as + noun = chẳng hạn như (mục 2.7)","such as + danh từ / V-ing; cloth bags = túi vải"]'::jsonb, 'B1', '9. Môi trường'),
    (74, 'Đã đến lúc các nhà máy phải chuyển sang nguồn năng lượng sạch hơn.', 'It is high time factories switched to cleaner sources of energy.', '["It is high time that factories switched to cleaner sources of energy.","It is high time factories switched to cleaner energy sources.","It''s high time factories switched to cleaner sources of energy.","It is high time factories moved to cleaner sources of energy."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.8)","sau high time: S + V quá khứ (switched)"]'::jsonb, 'C1', '9. Môi trường'),
    (75, 'Chỉ bằng cách trồng lại rừng thì chúng ta mới bảo vệ được động vật hoang dã.', 'Only by replanting forests can we protect wildlife.', '["Only by replanting forests can we protect wild animals.","Only by restoring forests can we protect wildlife.","Only by reforesting land can we protect wildlife."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.10)","đảo ngữ: can + we; replant forests = trồng lại rừng"]'::jsonb, 'C1', '9. Môi trường'),
    (76, 'Ô nhiễm không khí đã trở thành mối lo ngại ngày càng lớn ở các thành phố công nghiệp.', 'Air pollution has become a growing concern in industrial cities.', '["Air pollution has become a growing concern in many industrial cities.","Air pollution has become a pressing issue in industrial cities."]'::jsonb, '["a pressing issue / a growing concern = vấn đề cấp bách / mối lo ngại ngày càng lớn (mục 2.12)","industrial cities = thành phố công nghiệp"]'::jsonb, 'B2', '9. Môi trường'),
    (77, 'Ngân hàng số giúp người dân nông thôn có khả năng chuyển tiền mà không cần đến chi nhánh.', 'Digital banking enables rural residents to transfer money without visiting a branch.', '["Digital banking enables people in rural areas to transfer money without visiting a branch.","Digital banking enables rural residents to send money without visiting a branch.","Digital banking enables rural people to transfer money without going to a branch.","Online banking enables rural residents to transfer money without visiting a branch."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","transfer money = chuyển tiền; without + V-ing"]'::jsonb, 'B2', '10. Công nghệ'),
    (78, 'Thông báo liên tục tước đi của người lao động khoảng thời gian cần thiết để tập trung.', 'Constant notifications deprive workers of the time they need to concentrate.', '["Constant notifications deprive employees of the time they need to concentrate.","Constant notifications deprive workers of the time they need to focus.","Constant notifications deprive workers of the time needed to concentrate.","Continuous notifications deprive workers of the time they need to concentrate."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","notifications = thông báo; concentrate = tập trung"]'::jsonb, 'C1', '10. Công nghệ'),
    (79, 'Mạng xã hội có thể có tác động tiêu cực đến lòng tự trọng của thanh thiếu niên.', 'Social media can have a negative impact on teenagers'' self-esteem.', '["Social media may have a negative impact on teenagers'' self-esteem.","Social media can have a negative impact on the self-esteem of teenagers.","Social networks can have a negative impact on teenagers'' self-esteem.","Social media can have a negative impact on young people''s self-esteem."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","self-esteem = lòng tự trọng"]'::jsonb, 'B2', '10. Công nghệ'),
    (80, 'Từ góc nhìn của tôi, công nghệ nên hỗ trợ giáo viên chứ không thay thế họ.', 'From my perspective, technology should support teachers rather than replace them.', '["From my perspective, technology should support teachers, not replace them.","From my perspective, technology should assist teachers rather than replace them.","From my perspective, technology should help teachers rather than replace them."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","rather than = chứ không"]'::jsonb, 'B2', '10. Công nghệ'),
    (81, 'Dù đúng là tự động hóa làm mất một số việc làm, nó cũng tạo ra những loại công việc mới.', 'While it is true that automation destroys some jobs, it also creates new types of work.', '["While it is true that automation eliminates some jobs, it also creates new types of work.","While it is true that automation destroys some jobs, it also creates new kinds of jobs.","While it is true that automation causes some job losses, it also creates new types of work.","While it''s true that automation destroys some jobs, it also creates new types of work."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","automation = tự động hóa"]'::jsonb, 'C1', '10. Công nghệ'),
    (82, 'Trí tuệ nhân tạo có thể cải thiện ngành y tế, miễn là dữ liệu của bệnh nhân được bảo vệ đúng cách.', 'Artificial intelligence can improve healthcare, provided that patient data is properly protected.', '["Artificial intelligence can improve healthcare, as long as patient data is properly protected.","AI can improve healthcare, provided that patient data is properly protected.","Artificial intelligence can improve healthcare, provided that patients'' data is properly protected.","Artificial intelligence can improve healthcare, provided that patient data is protected properly."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.9)","patient data = dữ liệu bệnh nhân"]'::jsonb, 'B2', '10. Công nghệ'),
    (83, 'Không còn nghi ngờ gì rằng Internet đã thay đổi cách con người học tập.', 'There is no doubt that the Internet has changed the way people learn.', '["There is no doubt that the Internet has changed how people learn.","There is no doubt that the Internet has transformed the way people learn.","There''s no doubt that the Internet has changed the way people learn.","There is no doubt that the Internet has changed the way people study."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.10)","the way + S + V = cách mà …"]'::jsonb, 'B2', '10. Công nghệ'),
    (84, 'Xe tự lái chắc chắn sẽ thay đổi ngành vận tải trong thập kỷ tới.', 'Self-driving cars are set to transform the transport industry over the next decade.', '["Self-driving cars are set to change the transport industry over the next decade.","Self-driving cars are set to transform the transport industry in the next decade.","Driverless cars are set to transform the transport industry over the next decade.","Self-driving cars are set to transform the transportation industry over the next decade."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.11)","the next decade = thập kỷ tới"]'::jsonb, 'C1', '10. Công nghệ'),
    (85, 'Ứng dụng gọi xe cho phép mọi người đặt chuyến đi chỉ trong vài giây.', 'Ride-hailing apps allow people to book a journey in just a few seconds.', '["Ride-hailing apps allow people to book a ride in just a few seconds.","Ride-hailing apps allow people to book a trip in just a few seconds.","Ride-hailing apps allow users to book a journey in just a few seconds.","Ride-hailing apps allow people to book a journey in a few seconds."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","ride-hailing apps = ứng dụng gọi xe"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (86, 'Phụ thuộc vào ứng dụng giao đồ ăn có thể dẫn đến lối sống ít vận động.', 'Relying on food delivery apps can lead to an inactive lifestyle.', '["Relying on food delivery apps can lead to a sedentary lifestyle.","Relying on food delivery apps may lead to an inactive lifestyle.","Depending on food delivery apps can lead to an inactive lifestyle.","Overreliance on food delivery apps can lead to an inactive lifestyle."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","rely on sth = phụ thuộc vào; inactive lifestyle = lối sống ít vận động"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (87, 'Với tôi thì có vẻ như mọi người dùng thời gian tiết kiệm được cho màn hình thay vì cho gia đình.', 'It seems to me that people spend the time they save on screens instead of with their families.', '["It seems to me that people spend the time they save on screens rather than with their families.","It seems to me that people spend the time they save on screens instead of on their families.","It seems to me that people spend the saved time on screens instead of with their families."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","spend time on sth / with sb = dành thời gian cho"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (88, 'Dù rất thích mua sắm trực tuyến, nhiều người thừa nhận nó làm giảm giao tiếp trực tiếp.', 'Much as people enjoy online shopping, many admit that it reduces face-to-face contact.', '["Much as people enjoy shopping online, many admit that it reduces face-to-face contact.","Much as people enjoy online shopping, many admit it reduces face-to-face contact.","Much as people enjoy online shopping, many admit that it reduces face-to-face interaction.","Much as people like online shopping, many admit that it reduces face-to-face contact."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","face-to-face contact = giao tiếp trực tiếp"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (89, 'Theo nhiều người lao động, lợi ích của giờ làm việc linh hoạt lớn hơn bất lợi.', 'According to many workers, the advantages of flexible working hours outweigh the disadvantages.', '["According to many workers, the benefits of flexible working hours outweigh the drawbacks.","According to many employees, the advantages of flexible working hours outweigh the disadvantages.","According to many workers, the advantages of flexible hours outweigh the disadvantages.","For many workers, the advantages of flexible working hours outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","flexible working hours = giờ làm việc linh hoạt"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (90, 'Điều này đặc biệt rõ ở các thành phố lớn, nơi mọi người mất hàng giờ đi lại mỗi ngày.', 'This is particularly evident in big cities, where people spend hours commuting every day.', '["This is particularly evident in large cities, where people spend hours commuting every day.","This is particularly evident in big cities, where people spend hours travelling to work every day.","This is particularly evident in big cities, where people spend hours commuting each day."]'::jsonb, '["This is particularly evident in … = điều này đặc biệt rõ ở (mục 2.7)","spend + thời gian + V-ing; commute = đi lại (đi làm)"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (91, 'Điều mà các bậc cha mẹ bận rộn cần nhất là thêm thời gian bên con.', 'What busy parents need most is more time with their children.', '["What busy parents need most is more time with their kids.","What busy parents need most is more time to spend with their children.","What busy parents most need is more time with their children."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.10)","What + S + V + is … = điều mà … là …"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (92, 'Ngày càng nhiều người dùng máy rửa bát và robot hút bụi để tiết kiệm thời gian làm việc nhà.', 'More and more people are using dishwashers and robot vacuums to save time on housework.', '["More and more people use dishwashers and robot vacuums to save time on housework.","More and more people are using dishwashers and robot vacuum cleaners to save time on housework.","More and more people are using dishwashers and robot vacuums to save time on household chores."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.11)","save time on sth = tiết kiệm thời gian cho"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (93, 'Những hy sinh trước mắt có thể mở đường cho sự thịnh vượng lâu dài.', 'Short-term sacrifices can pave the way for long-term prosperity.', '["Short-term sacrifices could pave the way for long-term prosperity.","Short-term sacrifices may pave the way for long-term prosperity.","Short-term sacrifices can pave the way to long-term prosperity."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","prosperity = sự thịnh vượng"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (94, 'Những thay đổi chính sách đột ngột có thể làm nảy sinh sự phản đối của người dân trong ngắn hạn.', 'Sudden policy changes can give rise to public opposition in the short term.', '["Sudden policy changes may give rise to public opposition in the short term.","Sudden changes in policy can give rise to public opposition in the short term.","Sudden policy changes can give rise to public resistance in the short term.","In the short term, sudden policy changes can give rise to public opposition."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","public opposition = sự phản đối của người dân; in the short term = trong ngắn hạn"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (95, 'Mặc dù xe điện đắt hơn lúc mua, theo thời gian chúng tốn ít chi phí vận hành hơn nhiều.', 'Although electric cars are more expensive to buy, they cost much less to run over time.', '["Even though electric cars are more expensive to buy, they cost much less to run over time.","Although electric cars cost more to buy, they cost much less to run over time.","Although electric cars are more expensive to buy, they are much cheaper to run over time."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","cost less to run = tốn ít chi phí vận hành"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (96, 'Các nhà hoạch định chính sách phải cân bằng giữa chi phí trước mắt và lợi ích lâu dài.', 'Policymakers must strike a balance between short-term costs and long-term benefits.', '["Policymakers have to strike a balance between short-term costs and long-term benefits.","Policy makers must strike a balance between short-term costs and long-term benefits.","Policymakers must strike a balance between immediate costs and long-term benefits."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.8)","policymakers = nhà hoạch định chính sách"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (97, 'Trừ khi những thay đổi được đưa ra từng bước, nhiều người lao động sẽ khó thích nghi.', 'Unless changes are introduced gradually, many workers will struggle to adapt.', '["Unless changes are introduced step by step, many workers will struggle to adapt.","Unless the changes are introduced gradually, many workers will struggle to adapt.","Unless changes are made gradually, many workers will struggle to adapt.","Unless changes are introduced gradually, many workers will find it hard to adapt."]'::jsonb, '["unless + clause = trừ khi (mục 2.9)","sau unless không dùng not; struggle to V = khó khăn để"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (98, 'Giá mà chính phủ đầu tư vào năng lượng tái tạo từ mười năm trước, đất nước đã tiết kiệm được hàng tỷ đô la tiền nhập khẩu nhiên liệu.', 'Had the government invested in renewable energy ten years ago, the country would have saved billions of dollars on fuel imports.', '["Had the government invested in renewable energy a decade ago, the country would have saved billions of dollars on fuel imports.","Had the government invested in renewable energy ten years ago, the country would have saved billions of dollars in fuel imports.","Had the government invested in renewable energy ten years ago, the nation would have saved billions of dollars on fuel imports."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.9)","đảo ngữ, không dùng If; fuel imports = nhập khẩu nhiên liệu"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (99, 'Trang trại điện gió mới có khả năng hoàn vốn trong vòng mười lăm năm.', 'The new wind farm is likely to pay for itself within fifteen years.', '["The new wind farm is likely to pay for itself within 15 years.","The new wind farm is likely to pay off within fifteen years.","The new wind farm is likely to recover its costs within fifteen years."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.11)","wind farm = trang trại điện gió; pay for itself = tự hoàn vốn"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (100, 'Những quyết định hôm nay sẽ có hậu quả sâu rộng đối với các thế hệ tương lai.', 'Decisions made today will have far-reaching consequences for future generations.', '["The decisions made today will have far-reaching consequences for future generations.","Decisions we make today will have far-reaching consequences for future generations.","Today''s decisions will have far-reaching consequences for future generations."]'::jsonb, '["have far-reaching consequences for sth = có hậu quả sâu rộng đối với (mục 2.12)","future generations = các thế hệ tương lai"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn')
  ) as s (n, vi, en, alt, hints, level, topic);
end $$;

-- Kiểm tra: phải thấy 1 dòng, so_cau = 100
select f.name, count(s.id) as so_cau
from public.sentence_folders f
left join public.sentences s on s.folder_id = f.id and s.deleted_at is null
where f.name = '12 hướng phát triển ý · pattern mục 2' and f.deleted_at is null
group by f.id, f.name;
